status = "official"
sha256 = "6d4995d2e7f1f24e062f52f600f33cceabe24e3055927e668dbea6a5dd0c5ea2"

# quant1 and setname1: used by giac_math1's formal properties, and by premises
# (set1.in(x, setname1.R) declares x real).
[cd.quant1]
