status = "official"
sha256 = "746cc460c6aec8601d72dbfe16b99451dcd24f165b2d9ec4f77b4f391bd54abd"

# prog1 (experimental): its assignment is the request that sets a session's
# variable, used only inside the envelope's call and when enabled.
[cd.prog1]
